#pragma once
#include <chrono>
#include <deque>
#include <functional>
#include <optional>
#include <unordered_map>
#include "log/Logger.hpp"

class HeapTimer {
public:
    using Clock = std::chrono::steady_clock;
    using TimeOutCallback = std::function<void(int)>;

    explicit HeapTimer(log::Logger::Ptr logger = log::RootLogger()) noexcept;
    ~HeapTimer() = default;

    void Push(const int& key, Clock::duration expiration, TimeOutCallback callback) noexcept;
    void Push(const int& key, Clock::time_point expiration, TimeOutCallback callback) noexcept;

    void Adjust(const int& key, Clock::duration expiration);
    void Adjust(const int& key, Clock::time_point expiration);

    void Tick() noexcept;
    bool Remove(const int& key) noexcept;
    void Invoke(const int& key);
    int Pop() noexcept;
    void Clear() noexcept;
    bool Contain(const int& key) const noexcept;
    bool Empty() const noexcept;
    std::size_t Size() const noexcept;
    Clock::duration ToNextTick() noexcept;

private:
    struct Node {
        int key;
        Clock::time_point expiration;
        TimeOutCallback callback;

        bool Expired() const noexcept;
        void Swap(Node&) noexcept;
    };

    log::Logger::Ptr logger_;
    std::unordered_map<int, std::size_t> key_to_idx_;
    std::deque<Node> nodes_;

    void ShiftUp(std::size_t idx) noexcept;
    void ShiftDown(std::size_t idx) noexcept;
    std::optional<std::size_t> Parent(std::size_t idx) const noexcept;
    std::optional<std::size_t> SmallChild(std::size_t idx) const noexcept;

    void Swap(std::size_t idx1, std::size_t idx2) noexcept;
    bool ValidIndex(std::size_t idx) const noexcept;
    int RemoveByIndex(std::size_t idx) noexcept;
};
